INSERT INTO Definition (word_id, language_id, pos_id, definition, example)
VALUES (11872,3,1,'နှစ်ဆယ့်ခြောက်လုံးမြောက်မွန်ဗျည်း။',NULL)
,(11873,3,1,'ပွဲလျက်။',NULL)
,(11873,3,2,'သင်။ မင်း။','“ယဟွံတီတဲ၊ ပမွဲသွတ်သွာ။ ညံၚ်အဲကဵုယ၊ စံဒြဟတ်ကၠာ။” (လိက်သောဝိန်ဇဲယ။ မာံရောဂေါ။) = “ငါ့လက်စွမ်းကို မင်းမသိဘဲ အထင်သေး၏၊ ငါနှင့်မင်း အစွမ်းအားပြိုင်ကြစို့။”')
,(11874,3,1,'‘ရခေၚ်’ (န) ရှု။',NULL)
,(11875,3,10,'(န) ယတိ။ (ကဗျာရေးရာ ရွတ်ဖတ်ရာ­ တန့်ရပ်ရသော အပိုင်းအခြား။)','“လိက်ဝွံကၠာတုဲ၊ ဆန်တုဲမွဲဝါ။ — ဂၠိုၚ်ဂိတုသၞာံ၊ ပယာံအခါ။ ပိုတ်ဗျန်မူလ၊ ယတိယောၚ်ယာ။” (လိက်ဝါရဝေါၚ်သ။ အစွောံ။) = “ဤပျို့ကဗျာကို ရှေးတစ်ခါ ဖွဲ့ဆိုစီကုံးခဲ့ပြီးပြီ။ နှစ်လကာလများစွာကြာသောအခါ မူလပုဒ်၊ ဗျည်း၊ ယတိတို့သည် ချွတ်ချော်ပျက်ယွင်းသွားခဲ့ကုန်၏။”')
,(11876,3,1,'လှေ၊ သင်္ဘောစသည် ဖာထေးရသည့် အင်ပင်၊ အင်ကြင်းပင်တို့မှထွက်သောအစေး။ အၚ်တွဲ။ ပွဲလျက်။ (ပါဠိ—သဇ္ဇုလသ)',NULL)
,(11877,3,16,'ထိုလူ။ ဟိုလူ။ ဟိုကောင်။','“စိုတ်ယတေံသၠုၚ် မာန်ယတေံဇၞော်။” (အာန်ဇုနာန်) = “ဟိုလူ၏စိတ်သည် ထောင်လွှား၏၊ ဟိုလူ၏မာနသည် ကြီး၏။”')
,(11878,3,10,'(န) မှန်ကန်ညီညွတ်ခြင်း။ အမှန်အတိုင်းဖြစ်ခြင်း။ ယထာဘူတ။',NULL)
,(11879,3,1,'အိုမင်းရင့်ရော်သောယောကျာ်း။ ပစ္ဆိမအရွယ်ယောကျာ်း။ (အသက် (၆ဝ) မှ (၉ဝ) အထက်အထိ အရွယ်ရှိသောအဘိုးအို။)/လူ့သက်တမ်း (၉ဝ) ဖြင့် တွက်ထားသည်။','“ယဗြဴကဵုယထဴ ညးၜါတြုံကဵုဗြဴ ပၞတ်ရၚ်သ္ကံ။” (ပြကိုဟ်ဂဝမ္ပတိ) = “အဘွားအိုနှင့်အဘိုးအို လင်မယားနှစ်ယောက်တို့သည် အချင်းချင်းစိတ်ဆိုးကြ၏။” || ‘လထဴ’ နှင့် ‘သၟတ်တြုံ’ တို့လည်းရှု။')
,(11880,3,1,'အိုမင်းရင့်ရော်သောမိန်းမ။ ပစ္ဆိမအရွယ်မိန်းမ။ သက်ကြီးအိုမ။ (အသက် (၆ဝ) မှ (၉ဝ) အထက်အထိ အရွယ်ရှိသောအဘွားအို။)/လူ့သက်တမ်း (၉ဝ) ဖြင့် တွက်ထားသည်။','‘လဗြဴ’ နှင့်‘သၟတ်ဗြဴ’ တို့လည်းရှု။ || “ပ္ဍဲဇရေၚ်သုသာန်ဂှ် ယဗြဴလုပ်အာဂိုဟ်မွဲရ။” (ဇ—၄၃၂။ အစွောံ။) =“သုသာန်အရပ်­ အဘွားအိုသည် တစ်ခုသောဂူသို့ ဝင်သွား၏။”')
,(11881,3,1,'အမည်။','မၞုံယၟု၊ ဂးယၟု = အမည်ရှိသော၊ အမည်တွင်သော။')
,(11882,3,1,'အမည်နာမ။',NULL)
,(11883,3,11,'(န) ယမိုက်ကျမ်း။',NULL)
,(11884,3,1,'ငိုခြင်း။ အငို။','‘မိၚ်ဗရုယွာံကောန်ၚာ်ဂှ်တုဲ—။’ (ဇ—၁၂။ အစွောံ။) = ‘ထိုကလေး၏ငိုသံကိုကြား၍—။’ || “နယွာံမဇၞော်ဂှ် ထေရ်ဗျုဂှ် ဂတေဝ်ယာံတုဲ—။” (ဇ—၃၇၂။ အစွောံ) = “ရဟန်းအိုကြီးသည် ကြီးစွာသောငိုခြင်းဖြင့် သည်းစွာငို၏။” || ‘ယာံ’ (ကြိ) လည်းရှု။')
,(11885,3,1,'အသက်ရှူခြင်း။','ယဝီုတိတ်ယဝီုလုပ် = ထွက်သက်ဝင်သက်။ || ‘ယီု’ (ကြိ) လည်းရှု။')
,(11886,3,10,'(န) ကျော်စောခြင်း။',NULL)
,(11887,3,1,'ရွက်ထည်။','‘ဖျေံတၟအ်ပၠအ်ယာ’ = ‘ကျောက်ချ၍ ရွက်ထည်ကိုဖြေလျှော့သည်။ ရပ်နားသည်။’')
,(11887,3,4,'မသည်။ ပင့်သည်။ ကြွသည်။','“(ခ္ဍာ်ဂှ်) ဇိုၚ်မွဲဂှ် ဍေံယာပၚ်လဝ်ရ။” (ဇ—၃၈၄။အစွောံ။) = “ထိုကျီးသည် ခြေတစ်ဖက်ကို ကြွ၍ပင့်ထား၏။”')
,(11888,3,10,'(န) သွားခြင်း။ ကြွမြန်းခြင်း။','သ္ပယာတြာ = သွားသည်။ ကြွမြန်းသည်။ || “ယြဴဨကရာတ်တံ မပယာကြာဂှ်။” (ပြကိုဟ်နဝဗျတ္တိ) = “အကြင်မင်းဧကရာဇ်တို့ ကြွမြန်းခြင်းပြုရာ­။” || “လမုဟ်ကောန်ဂၞဴ၊ ပတဴယာတြာ။” (လိက်သောဝါနနဟောၚ်) = “ယခုသားတော်မောင် ကြွမြန်းပါမည်။” || “ကောန်ဗၠာဲသၟိက်အာ၊ ရာထာန်မိမ။ သၟိက်ပယာကြာ၊ အာဂွံကီုရ။” (လိက် ကောန်သၟိၚ်ပိ။ မာံခစုန်အံက်။) = “မိဘအရပ်ဋ္ဌာနသို့ သားသွားလိုပါက ကြွမြန်းသွားနိုင်ပါပြီ။”')
,(11888,3,10,'(ကြိ) သွားသည်။ ကြွမြန်းသည်။','“အဲအာမ္ဂး သၟိၚ်လေဝ် ယာကြာအာကီုရ။” (သုဓမ္မဒေသနာ။ ဂရိုက်သာံ။) = “ငါသွားလျှင် ဘုရင်သည်လည်း ကြွမြန်းသွားလတ္တံ့။” || “လၟုဟ်ပိုဲဍိက်၊ သၟိက်ယာကြာရ။” (လိက်ပတ္တစာရဳ။ နာဲထဝ်စိုပ်။) = “ယခုအကျွန်ုပ်တို့ သွားချင်ပါပြီ။” || “လမုဟ်အဲဍိက်၊ သၟိက်ဂွံယာတြာ။” (လိက်သောဝါနနဟောၚ်)')
,(11889,3,10,'(န) ဆန်ပြုတ်။ ယာဂု။ ယက်မန်း။',NULL)
,(11890,3,1,'မုတ်ခါး။',NULL)
,(11891,3,1,'အဖျော်ယမကာ။','ဍာ်ယာမ = ဖျော်ရည်။')
,(11892,3,10,'(နဝိ) ယာယီဖြစ်သော။ ခေတ္တမျှသာဖြစ်သော။',NULL)
,(11892,3,10,'(ကြိ) ရွှေ့ပြောင်းတတ်သည်။ ရွေ့လျားသည်။ သွားသည်။ ကြွမြန်းသည်။','“မာတ်သၚ်ကြာန်ဒး၊ အကးယာယဳ။” (လိက်မေဃသန်) = “သင်္ကြန်အခါရောက်သော် မိုးတိမ်တို့သည် ရွေ့လျားတတ်ကုန်၏။” || “ဒးအခိၚ်ကၠာ၊ကာလယာယဳ။” (လိက်မိဒေဝကိနနရဳ။ နာဲသိုက်ဇု။) = “သွားရန်အချိန်တန်သည်။” || “ဨကရာတ်ကဵုစဳရေၚ် လၟေၚ်လၟေၚ်ဗဵုပၞာန် ဗွဲဂတကြဴတုဲ ယာယဳဇက်အာရ။” (သၠပတ်ရာဇာသာန်) =“ဘုရင်သည် စစ်သည်ဗိုလ်ပါကို ရှေ့နောက်အစဉ်အားဖြင့် စီရင်စေ၍ ကြွမြန်းထွက်ချီသွား၏။” || “ကဵုစဳရေၚ်ပၞာန်၊ ထာန်တိုက်ယာန်ကွဳ။ ဖန်ဖက်တဴကၠာ၊ သွက်သၟိၚ်ယာယဳ။” (လိက်မေဃကောန်ဒြာဲ) = “ခြေသည်တပ်၊ ရထားတပ်စသည်ဖြင့် စစ်ကိုစီရင်စေ၍ ဘုရင်ကြွမြန်းရန်အတွက် စီစဉ်ထား၏။”')
,(11893,3,4,'သွားသည်။ လာသည်။ ကြွမြန်းသည်။','“ကာလဂှ်ဟေၚ်၊ အကေၚ်ကောရ၊ မပယာယဳ။ မိတ်ဂွိုၚ်ကျာ်သြဳ၊ စမှဳဒၟံၚ်မ၊ လတေအ်ရရဴ။” (ဇၟန်လိက်မန်တြေံတြဟ်) = “ချစ်သူမောင်ကြွမြန်းလာမြဲအချိန်­ ချစ်သူမယ်သည် အခါတိုင်းကဲ့သို့ပင် စောင့်မျှော်နေပါ၏။”')
,(11894,3,11,'(န) ယုဂန္ဓိုရ်တောင်။ (တောင်စဉ်ခုနစ်ထပ်တွင် အတွင်းအကျဆုံးဖြစ်ပြီး နေလသွားလမ်းနှင့် အမြင့်တစ်ညီတည်းဖြစ်သော ကျမ်းဂန်လာတောင်။) (ပါဠိ—ယုဂန္ဓရ)','“ညံၚ်သၟိၚ်တ္ၚဲဗၠာဲ မဆာဲဒၟံၚ်က္ဍိုပ်တၟံယုဂ္ဂန္ဓဝ်ကီု။” (ဇ—တေမဳ။ အစွောံ။) = “ယုဂန္ဓိုရ်တောင်ထိပ်­ တင့်တယ်လျက်နေသော နေမင်းပျိုကဲ့သို့။”')
,(11895,3,10,'(န) ပျိုရွယ်သောယောကျာ်း။ ယုဝ။',NULL)
,(11896,3,10,'(န) ပျိုရွယ်သောမိန်းမ။ ယုဝတီ။',NULL)
,(11897,3,4,'ခုန်သည်။','“ကောန်ၚာ်တအ် ယူဝေၚ်ဒၟံၚ်လ္တူသ္ၚိရ။” = “ကလေးများသည် အိမ်ပေါ်တွင်ခုန်ကစားနေကြသည်။” || “သုၚ်စဗၜူ၊ ယူဒၟံၚ်လျလျ။” (လိက်ဇိဝှစက္က) = “သောက်စားမူးယစ်၍ ဖြည်းဖြည်းသာသာခုန်နေကြ၏။”')
,(11898,3,4,'(မွန်ရိုးရာ) နတ်ကသည်။ နတ်ပွဲကျင်းပသည်။',NULL)
,(11899,3,10,'(နဝိ) အများအားဖြင့်ဖြစ်သော။ ယေဘုယျ။','ဗွဲယေဘုယျ = အများအားဖြင့်။ယေဘုယျအားဖြင့်။')
,(11900,3,14,'(န) ယေရှုခရစ်။ ခရစ်တော်။ (အင်္ဂလိပ်၊ Jesus Christ)',NULL)
,(11901,3,1,'ရောဂါ။','(ကြိ) ဖျားနာသည်။')
,(11902,3,1,'ဖုရောင်နာ။',NULL)
,(11903,3,1,'ပွေးရောဂါ။',NULL)
,(11904,3,1,'ရေယုန်နာ။','“ဂန္ဓမာလာ၊ ပါယဲကသေန်။” (လိက်ဇမ္ဗူပတိ။ မာံဒေံဍောတ်)')
,(11905,3,1,'အဆုတ်ရောဂါ။',NULL)
,(11906,3,1,'ကပ်ရောဂါ။ လူအစုလိုက်အပြုံလိုက် တစ်ချိန်တည်းဖြစ်သောရောဂါ။',NULL)
,(11907,3,1,'နူနာရောဂါ။',NULL)
,(11908,3,1,'နှလုံးရောဂါ။',NULL)
,(11909,3,1,'လည်ချောင်းရောဂါ။ လည်ချောင်းနာရောဂါ။',NULL)
,(11910,3,1,'ခေါင်းကိုက်ရောဂါ။',NULL)
,(11911,3,1,'အူအတက်ပေါက်ရောဂါ။',NULL)
,(11912,3,1,'လေထိုးနာ။ လေအောင့်နာ။',NULL)
,(11913,3,1,'သည်းခြေရောဂါ။',NULL)
,(11914,3,1,'အူကျရောဂါ။',NULL)
,(11915,3,16,'(န) ဖွတ်စအိုနာ။ (ပါဠိ—နာသိကရောဂ)',NULL)
,(11916,3,1,'(အမှောင့်ပယောဂ စသည်ကြောင့်မဟုတ်သော) သွေးရိုးသားရိုးရောဂါ။',NULL)
,(11917,3,1,'နူနာရောဂါ။',NULL)
